        J = thomas_jacobian(state, b)
        for c in range(3):
            Q[:, c] = Q[:, c] + dt * (J @ Q[:, c])
        if (i + 1) % renorm_every == 0:
            Q_r, R = np.linalg.qr(Q)
            for k in range(3):
